import sys
from collections import defaultdict

def main():
    input = sys.stdin.read().split()
    idx = 0

    n = int(input[idx]); idx += 1
    m = int(input[idx]); idx += 1

    adj = defaultdict(list)
    for _ in range(m):
        u = int(input[idx]); idx += 1
        v = int(input[idx]); idx += 1
        adj[u].append(v)
        adj[v].append(u)

    q_val = int(input[idx]); idx += 1
    queries = []
    for _ in range(q_val):
        queries.append(int(input[idx])); idx += 1

    pos = [0] * (n + 1)
    for i in range(1, n + 1):
        pos[i] = i

    cnt = [0] * (n + 1)
    for i, neighbors in enumerate(adj.items()):
        if i == 0:
            continue
        u = i
        for v in neighbors:
            if pos[u] > pos[v]:
                cnt[u] += 1

    total = 0
    for i in range(1, n + 1):
            for j in adj[i]:
                if pos[i] > pos[j]:
                    total += cnt[j]

    results = []
    results.append(total)

    current_time = n
    for v in queries:
        current_time += 1
        old_pos = pos[v]
        new_pos = current_time
        pos[v] = new_pos

        for neighbor in adj[v]:
            if pos[neighbor] < old_pos:
                if pos[neighbor] < new_pos:
                    if pos[neighbor] < old_pos:
                        if pos[v] > pos[neighbor]:
                            total -= cnt[neighbor]
                        cnt[v] += 1
                        if pos[v] > pos[neighbor]:
                            total += cnt[neighbor]
            else:
                if pos[neighbor] < new_pos:
                    if cnt[neighbor] > 0:
                        if pos[neighbor] < old_pos:
                            pass
                        else:
                            total -= cnt[neighbor]
                    cnt[neighbor] += 1
                    if pos[neighbor] < new_pos:
                        total += cnt[neighbor]

        for neighbor in adj[v]:
            if pos[neighbor] > old_pos:
                if pos[neighbor] > new_pos:
                    if pos[neighbor] > old_pos:
                        if pos[neighbor] > pos[v]:
                            total -= cnt[neighbor]
                        cnt[neighbor] -= 1
                        if pos[neighbor] > pos[v]:
                            total += cnt[neighbor]
                else:
                    if cnt[neighbor] > 0:
                        if cnt[neighbor] > 0:
                            total -= cnt[neighbor]
                    cnt[neighbor] -= 1
                    if pos[neighbor] > new_pos:
                        total += cnt[neighbor]

        results.append(total)

    print('\n'.join(map(str, results)))

if __name__ == '__main__':
    main()
